'use strict';

var escape = require('../helpers/escape');

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	//Create the question
	var question = options.question ? options.question : 'decision',
		name = options.name ? options.name : question,
		attrib;

	//Default aligment
	var aligment = 'btn-group';

	//Detect if the component has a diferent aligment
	aligment = options.aligment === 'vertical' ? 'btn-group-vertical' : aligment;
	aligment = options.aligment === 'justified' ? 'btn-group btn-group-justified' : aligment;

	//Create each button
	var buttons = [];

	for (var i = 0; i < options.options.length; i++) {
		var option = options.options[i],
			text = option.text,
			value = option.value;

		if (text) {
			if (!value) {
				value = text;
			}
		} else if (value) {
			text = value;
		} else {
			continue; //no text or value, skip
		}

		attrib = escape.htmlAttributeEscape(JSON.stringify(option), { singleQuotes: true });

		buttons.push(
			'<label class="btn btn-default f3-decision">' +
				'<input type="radio" name="' + name + '" value="' + value + '" class="hidden" data-options=\'' + attrib + '\'>' +
				text +
			'</label>'
		);
	}

	//HTML
	attrib = escape.htmlAttributeEscape(JSON.stringify(options), { singleQuotes: true });

	var $html = $(
		'<div class="form-group f3-decisions" data-options=\'' + attrib + '\'>' +
			'<h3>' + question + '</h3>' +
			'<div class="' + aligment + '">' +
				buttons.join('') +
			'</div>' +
		'</div>'
	);

	//Bind change
	$html.find('input').on('change', function() {

		var $this = $(this);

		//Reset all buttons
		$html.find('.f3-decision').addClass('btn-default').removeClass('btn-primary');

		//If this is checked, set as active
		if ($this.is(':checked')) {

			$this.parent('.f3-decision').addClass('btn-primary').removeClass('btn-default');

		}

	})
	.on('click', function() {

		var options = $(this).data('options');

		//Publish the event
		PubSub.publish('f3.decision', {
			'trigger': this,
			'event': 'go',
			'branch': options.branch
		});

	});

	return $html;

}

function _read(options, value) {

	var result;

	for (var i = 0; i < options.options.length; i++) {
		var option = options.options[i],
			optValue = option.value,
			optText = option.text;

		if (optText) {
			if (!optValue) {
				optValue = optText;
			}
		} else if (optValue) {
			optText = optValue;
		} else {
			continue; //no text or value, skip
		}

		if (optValue === value) {
			result = {
				text: optText,
				value: optValue
			};
			break;
		}
	}

	if (!result) {
		return null;
	}

	result.question = options.question || 'decision';
	result.name = options.name || options.question;

	return result;

}

module.exports = {
	render: _render,
	read: _read,
	name: 'decision'
};
